function UICultivatePlayerUpgradeDialog:Awake()
    local argument   = self.controller.Argument
    local parameters = argument.parameters
    self.uiType      = parameters.uiType
    self.params      = parameters.params
    self.autoClose   = parameters.autoClose
    KTool.SetActive(self.LevelUpPanel.gameObject, self.uiType == UIType.LevelUp)
    if self.uiType == UIType.LevelUp then
        CriWareUtils.PlaySe(uiSheets.UI_Menu.path, uiSheets.UI_Menu.ui_player_level_up)
    end

    ---@type UnityEngine.UI.VerticalLayoutGroup
    self.InfoPanelLayout = KTool.GetComponent(self.InfoPanel.gameObject, VerticalLayoutGroupType)
    -- KTool.SetActive(self.FunctionCell.gameObject, false)

    UIEventProxy.Create(self.Bg.gameObject).onPointerClick = function(eventData)
        if self.play then return end
        UIModule.CloseDialog(self.controller)
    end
end

