                self.play = false

                -- 播完升级动画，自动关闭
                if self.autoClose then
                    UIModule.CloseDialog(self.controller)
                end
            end)
        end)

    end))
    return coWait
end

function UICultivatePlayerUpgradeDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        playerComponent:ClearRewardsDialogInfoByType(Constants.RewardDialogType.PlayerUpgrade)

        self:StopCo()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

