function UICultivatePlayerUpgradeDialog:InitLevelUpUI(oldLv, newLv)
    self.TxtLevelNumOld.text = self:GeneratedLevelText(oldLv)
    self.TxtLevelNum.text = self:GeneratedLevelText(newLv)
    -- self.TxtLevelNum2.text = self:GeneratedLevelText(newLv)
    --local funcCount = 0
    -------------------------------------
    --- 体力恢复
    local newExpInfo = cardConfMgr:GetPlayerExpByLevelId(newLv, oldLv)
    local rewards = newExpInfo.rewards
    local isShowHpRecovery = false
    for i, reward in ipairs(rewards) do
        local goodsId = checkNumber(reward.goodsId)
        if goodsId == Constants.Currency.HpId then
            isShowHpRecovery = checkNumber(reward.num) >  0
            self.HpNum.text = reward.num
            self.HpNode2HpNum.text = reward.num
            --funcCount = funcCount + 1
            break
        end
    end

    -------------------------------------
    --- 最大体力改变
    local appMax = checkNumber(GameUtils.GetPrivilegeCardAddNumByRefId(1, "ApMax"))
    local oldExpInfo = cardConfMgr:GetPlayerExpByLevelId(oldLv, oldLv)
    local oldHpMax = checkNumber(oldExpInfo.hpMax) + appMax
    local newHpMax = checkNumber(newExpInfo.hpMax) + appMax
    local isShowHpChange = oldHpMax ~= newHpMax
    if isShowHpChange then
        self.HpMaxNum1.text = oldHpMax
        self.HpMaxNum2.text = newHpMax
        --funcCount = funcCount + 1
    end

    -------------------------------------
    --- 战斗员等级上限
    local oldCardLevelLimit = CardProgressionUtils.GetCardLevelLimit(oldLv)
    local cardLevelLimit    = CardProgressionUtils.GetCardLevelLimit(newLv)
    local isShowCardLimit   = cardLevelLimit > oldCardLevelLimit

    if isShowCardLimit then
        self.LevelMaxNum1.text = oldCardLevelLimit
        self.LevelMaxNum2.text = cardLevelLimit
    end

    return isShowHpRecovery, isShowHpChange, isShowCardLimit
end


