function UICultivatePlayerUpgradeDialog:GeneratedLevelText(level)
    local t = {}
    level = string.format("%02d", level)
    for num in level:gmatch('%d') do
        table.insert(t, string.format("<sprite=%s>", num))
    end
    return table.concat(t)
end

function UICultivatePlayerUpgradeDialog:StopCo()
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
end


